syntax:
class AbstractBase {
    public:
        virtual void pureVirtualFunc() = 0;  // Pure virtual function declaration
        // Implementation note: The '= 0' indicates it's pure virtual. The compiler will not generate a function body and marks the class as abstract.
        virtual void anotherVirtualFunc() {}  // Regular virtual function; compiler generates a vtable entry with the actual address.
};  
// Note: Derived classes must override pure virtual functions to be instantiable. The compiler enforces this at link time, ensuring the vtable is fully populated.

code_example:
#include <iostream>

class AbstractShape {  // Abstract class due to pure virtual function
public:
    virtual void draw() = 0;  // Pure virtual function
    virtual ~AbstractShape() {}  // Virtual destructor for proper cleanup
};

class Circle : public AbstractShape {
public:
    void draw() override {  // Overrides the pure virtual function
        std::cout << "Drawing a circle" << std::endl;
    }
};

int main() {
    // AbstractShape obj;  // Error: Cannot instantiate abstract class
    Circle obj;  // OK: Circle overrides the pure virtual function
    AbstractShape* ptr = &obj;  // Polymorphic use
    ptr->draw();  // Runtime dispatch via vtable
    return 0;
}
